        return;
      }
      pm[action] = roles.split(',').map((r) => r.trim()).join(',');
    }
    const froms: Record<string, string> = {};
    for (const [key, date] of Object.entries(from)) {
      const d = date.trim();
      if (d === '') continue;
      if (!isDate(d)) {
        setError('A from-date must be a date (yyyy-mm-dd).');
