15	 *  `policyDate` is yyyy-mm-dd, or "" when there is none (the sheet's today is the policy date); `periodNumberingFrom` is yyyy-mm-dd, or "" when numbering by period is off; `cap` has two decimals, or is "" when there is none; `graceDays` is a whole number of days (not dated), or "" when closing periods by today is off; `entryDate` is yyyy-mm-dd, or "" when it is off (a new claim left undated takes the sheet's today); `pot` has two decimals (not dated), or is "" when there is none; `alertThreshold` has two decimals (not dated), or is "" when alerts are off; `parent` is the id of the sheet whose rates are used where this one has none (not dated), or "" when there is none; `fiscalStartMonth` is the month (1 to 12) the sheet's fiscal year starts on (not dated; "1" unless set).
16	 *  Those that carry a figure are as in force on the sheet's today when they were read; `dated` holds every value recorded for each of them, by key
17	 *  (clerk-limit, floor, terms, terms-<grade>, late-pct, cap, proof-threshold, proof-threshold-<grade>, note-threshold, grace-<grade>; a blank grace or grade's proof threshold is none (a grade with none uses the sheet's proof threshold); a blank clerk limit, cap, proof threshold or note threshold is none).
18	 *  `perms` is the roles each action is allowed to, as a comma separated list, or "" for the standing rule (open, settle, void and close
19	 *  by clerk and steward; reassign and reopen by steward). */
20	export type Settings = { clerkLimit: string; floor: string; terms: string; latePct: string; policyDate: string; periodNumberingFrom: string; gradeTerms: Record<Grade, string>; cap: string; graceDays: string; entryDate: string; pot: string; alertThreshold: string; parent: string; fiscalStartMonth: string; dated: Record<string, DatedValue[]>; perms: Record<PermAction, string> };
21	
22	/** The actions the permission matrix decides; each is kept (not dated) under perm-<action>. */
23	export const PERM_ACTIONS = ['open', 'settle', 'void', 'reassign', 'close', 'reopen'] as const;
24	export type PermAction = (typeof PERM_ACTIONS)[number];
25	
26	/** What the request carries: a setting left out (or blank, for the floor, terms, a grade's terms and late percent) is left as it is; a blank policy date is none.
27	 *  `from` is the from-date (yyyy-mm-dd) a dated setting is recorded from, by key; left out, it is the sheet's today.
28	 *  `perms` are the roles each action is allowed to, by action: left out is left as it is, blank is the standing rule. */
29	export type SettingsChange = {
30	  clerkLimit?: string;
31	  floor?: string;
32	  terms?: string;
33	  latePct?: string;
34	  policyDate?: string;
35	  periodNumberingFrom?: string;
36	  entryDate?: string;
37	  gradeTerms?: Partial<Record<Grade, string>>;
38	  /** A grade's grace days (days past a claim's due-by before it is overdue), by grade: left out is left as it is, blank is none. */
39	  gradeGrace?: Partial<Record<Grade, string>>;
40	  cap?: string;
41	  proofThreshold?: string;
42	  /** A grade's own proof threshold, by grade: left out is left as it is, blank is none (the sheet's is in force). */
43	  gradeProof?: Partial<Record<Grade, string>>;
44	  noteThreshold?: string;
45	  graceDays?: string;
46	  /** The pot a balanced pool's members cut by their shares (not dated): left out is left as it is, blank is none. */
47	  pot?: string;
48	  /** The due-total above which a person is alerted (not dated): left out is left as it is, blank is off. */
49	  alertThreshold?: string;
50	  /** The id of the parent sheet (not dated): left out is left as it is, blank is none. */
51	  parent?: string;
52	  /** The month (1 to 12) the fiscal year starts on (not dated): left out or blank is left as it is. */
53	  fiscalStartMonth?: string;
54	  from?: Record<string, string>;
