56	};
57	
58	export type RoleName = 'clerk' | 'steward' | 'viewer';
59	
60	/** The role a sheet gives a user name; a name with no entry is a clerk. */
61	export type Role = { user: string; role: RoleName };
62	
63	export const ROLES: RoleName[] = ['clerk', 'steward', 'viewer'];
64	
65	/** Under the sheet's key, so re-loading the sheet re-reads its settings and roles. */
66	export const settingsKey = (sheetId: string) => [...sheetKey(sheetId), 'settings'] as const;
67	export const rolesKey = (sheetId: string) => [...sheetKey(sheetId), 'roles'] as const;
68	
69	export const settingsQuery = (sheetId: string) => ({
70	  queryKey: settingsKey(sheetId),
71	  queryFn: () => getJson<Settings>(`/api/sheets/${encodeURIComponent(sheetId)}/settings`),
72	});
73	
74	/** A dated setting's value in force on the sheet's today, or `starting` when none is recorded on or before it. */
75	export function useCurrent(sheetId: string, key: string, starting = ''): string {
76	  const today = useSheetToday(sheetId);
77	  return valueOn(useQuery(settingsQuery(sheetId)).data?.dated?.[key], today) ?? starting;
78	}
79	
80	/** The sheet's floors by from-date: what a claim's live due is at least, as in force on the claim's date. */
81	export function useFloor(sheetId: string): DatedValue[] {
82	  return useQuery(settingsQuery(sheetId)).data?.dated?.floor ?? [];
83	}
84	
85	/** The sheet's cap in force on its today: what a person's due-total is at most ("" for none). */
86	export function useCap(sheetId: string): string {
87	  return useCurrent(sheetId, 'cap');
88	}
89	
90	/** The sheet's late percents by from-date: what an overdue claim gains of its figure for every full 30 days it is overdue, as in force on each 30-day boundary date (the due-by plus 30, 60, 90 ... days). */
91	export function useLatePct(sheetId: string): DatedValue[] {
92	  return useQuery(settingsQuery(sheetId)).data?.dated?.['late-pct'] ?? [];
93	}
94	
95	/** The sheet's policy date (yyyy-mm-dd): the one set, or the sheet's today when there is none. */
96	export function usePolicyDate(sheetId: string): string {
97	  const today = useSheetToday(sheetId);
98	  return useQuery(settingsQuery(sheetId)).data?.policyDate || today;
99	}
100	
101	/** What a claim's late charge and its rounding depend on, as the sheet has it now. */
102	export function useLate(sheetId: string): Late {
103	  const dated = useQuery(settingsQuery(sheetId)).data?.dated;
104	  return {
105	    grace: Object.fromEntries(GRADES.map((g) => [g, dated?.[`grace-${g}`] ?? []])),
106	    people: useQuery(peopleQuery(sheetId)).data ?? [],
107	    today: useSheetToday(sheetId),
108	    pct: useLatePct(sheetId),
109	    policy: usePolicyDate(sheetId),
110	    claims: useQuery(claimsQuery(sheetId)).data ?? [],
111	  };
112	}
113	
114	/** The month (1 to 12) the sheet's fiscal year starts on. */
115	export function useFiscalStartMonth(sheetId: string): number {
116	  return Number(useQuery(settingsQuery(sheetId)).data?.fiscalStartMonth || '1');
117	}
118	
119	/** The fiscal year a date (yyyy-mm-dd) falls in, named FY<yyyy> by the calendar year its first day falls in. */
120	export function fiscalYear(date: string, startMonth: number): string {
121	  const year = Number(date.slice(0, 4));
122	  const month = Number(date.slice(5, 7));
123	  return `FY${month >= startMonth ? year : year - 1}`;
124	}
125	
126	export const rolesQuery = (sheetId: string) => ({
127	  queryKey: rolesKey(sheetId),
128	  queryFn: () => getJson<Role[]>(`/api/sheets/${encodeURIComponent(sheetId)}/roles`),
129	});
